def split_legacy_config(apps, schema_editor):
    alias = schema_editor.connection.alias
    legacy = apps.get_model('characters', 'LLMConfig').objects.using(alias).filter(pk=1).first()
    if legacy is None:
        return
    provider, _ = apps.get_model('characters', 'LLMProvider').objects.using(alias).get_or_create(
        name='原 LLM 配置',
        defaults={
            'api_type': legacy.provider,
            'base_url': legacy.base_url,
            'api_key': legacy.api_key,
            'timeout': legacy.timeout,
            'max_retries': legacy.max_retries,
            'is_active': legacy.is_active,
        },
    )
    apps.get_model('characters', 'LLMModel').objects.using(alias).get_or_create(
        provider_id=provider.pk,
        model=legacy.model,
        defaults={
            'priority': 10,
            'max_tokens': legacy.max_tokens,
            'temperature': legacy.temperature,
            'is_active': True,
        },
    )


def restore_legacy_config(apps, schema_editor):
    alias = schema_editor.connection.alias
    model = apps.get_model('characters', 'LLMModel').objects.using(alias).select_related('provider').order_by(
        'priority', 'pk',
    ).first()
    if model is None:
        return
    provider = model.provider
    apps.get_model('characters', 'LLMConfig').objects.using(alias).update_or_create(
        pk=1,
        defaults={
            'provider': provider.api_type,
            'base_url': provider.base_url,
            'api_key': provider.api_key,
            'timeout': provider.timeout,
            'max_retries': provider.max_retries,
            'model': model.model,
            'max_tokens': model.max_tokens,
            'temperature': model.temperature,
            'is_active': provider.is_active and model.is_active,
        },
    )


